import heapq


def _ledger(data, revision_first, original_tax):
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_first:
            rank = (event.get("revision", 0), pos)
        else:
            rank = (seq, event.get("revision", 0), pos)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax_base = raw if original_tax else net
        tax = rounded(tax_base * event.get("tax_bp", 0), mode)
        value = net + tax
        if event.get("kind") == "refund":
            value = -value
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + value
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    rows = {name: {r["version"]: r for r in package_rows}
            for name, package_rows in packages.items()}
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted(rows[name], reverse=True)
        choices.append(versions + [-1])

    for vector in product(*choices):
        installed = {name: version for name, version in zip(names, vector) if version != -1}
        if any(name not in installed or not lo <= installed[name] <= hi
               for name, (lo, hi) in roots.items()):
            continue
        if any(name in installed and installed[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in installed.items()):
            continue

        edges = {}
        valid = True
        reachable = set()
        pending = list(roots)
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name not in installed:
                valid = False
                break
            row = rows[name][installed[name]]
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                active.append(dep)
                other = dep["name"]
                if other not in installed or not dep["min"] <= installed[other] <= dep["max"]:
                    valid = False
                    break
                pending.append(other)
            edges[name] = [dep["name"] for dep in active]
        if not valid or reachable != set(installed):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            state[name] = 2
            return True
        if any(not visit(name) for name in reachable):
            continue
        return {"versions": installed}
    return {"error": "unsatisfiable"}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked:
        return {"error": "impossible"}
    eligible = [job for job in jobs if job["id"] not in blocked]
    best = None
    best_value = None
    quotas = data.get("quotas", {})
    for subset in combinations(eligible, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        intervals = sorted((job["start"], job["end"]) for job in subset)
        ends = []
        feasible = True
        for start, end in intervals:
            while ends and ends[0] <= start:
                heapq.heappop(ends)
            heapq.heappush(ends, end)
            if len(ends) > 2:
                feasible = False
                break
        if not feasible:
            continue
        names = sorted(ids)
        value = sum(job["value"] for job in subset)
        if best is None or value > best_value or (value == best_value and names < best):
            best, best_value = names, value
    if best is None:
        return {"error": "impossible"}
    return {"selected": best, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, coupons - 1))
            next_node = edge["v"]
            next_mask = mask | bit.get(next_node, 0)
            for duration, left in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, left)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, left))
    return {"arrival": None}


